/* Durable edits: commit the outbox before clearing a form, then replay with receipts. */
(()=>{'use strict';
 const storeKey='goblin-sync-outbox-v2',cacheKey='goblin-sync-cache-v2';let jobs=[],cached=false,draining=false,identity=null,protocol=0;
 const network=callPc;let noteVersion=null;
 function load(){try{jobs=JSON.parse(localStorage.getItem(storeKey)||'[]');if(!Array.isArray(jobs))jobs=[]}catch(_){jobs=[]}try{const cache=JSON.parse(localStorage.getItem(cacheKey)||'null');if(cache?.base===pcUrl&&cache.pc){pc=cache.pc;identity=cache.identity||null;cached=true}}catch(_){}}
 function saveJobs(){const raw=JSON.stringify(jobs);if(raw.length>1500000)throw Error('Les modifications en attente sont trop volumineuses. Reconnecte le PC ou exporte une sauvegarde avant de continuer.');localStorage.setItem(storeKey,raw)}
 function id(){return 'sync-'+crypto.randomUUID()}
 function overlay(){for(const key of ['tasks','shopping','events','recipes']){pc[key]=(pc[key]||[]).filter(x=>!String(x.id).startsWith('local-'));for(const row of pc[key])delete row._pending}for(const job of jobs){if(job.base!==pcUrl||job.conflict)continue;const m=job.path.match(/^\/api\/(tasks|shopping|events|recipes)(?:\/(\d+))?$/);if(!m)continue;const rows=pc[m[1]]||[];if(job.method==='POST'){const temp='local-'+job.id;if(!rows.some(x=>x.id===temp))rows.push({...job.data,id:temp,_pending:true})}else{const row=rows.find(x=>String(x.id)===m[2]);if(row)Object.assign(row,job.data,{_pending:true})}}for(const key of ['tasks','shopping','events','recipes'])pc[key]=(pc[key]||[]).filter(x=>!x.archived)}
 function cache(){try{const clean=JSON.parse(JSON.stringify(pc));for(const key of ['tasks','shopping','events','recipes'])clean[key]=(clean[key]||[]).filter(x=>!String(x.id).startsWith('local-'));localStorage.setItem(cacheKey,JSON.stringify({base:pcUrl,pc:clean,identity}));cached=true}catch(e){error='Cache hors ligne non enregistré : exporte une sauvegarde et libère un peu de place.'}}
 async function capabilities(){const c=await network('GET','/api/sync/capabilities');if(c.protocol!==2||!c.idempotent_writes||!c.field_conflicts)throw Error('Mets L’Atelier Windows à jour pour envoyer ces modifications en sécurité.');protocol=2;if(identity&&c.installation_id&&identity!==c.installation_id)throw Error('Cette adresse correspond à une autre installation. Les modifications en attente sont conservées.');identity=c.installation_id||identity;return c}
 async function drain(){if(draining||!pcUrl||!jobs.some(j=>j.base===pcUrl&&!j.conflict))return;const before=JSON.stringify(jobs);draining=true;try{await capabilities();for(const job of [...jobs]){if(job.base!==pcUrl||job.conflict)continue;try{await network(job.method,job.path,{...job.data,_sync:{id:job.id,...(job.method==='PUT'?{base:job.original}:{})}});jobs=jobs.filter(x=>x.id!==job.id);saveJobs()}catch(e){if(e.status===409){job.conflict=e.message;saveJobs();continue}error='Modifications gardées sur ce téléphone : '+e.message;online=false;break}}}catch(e){error=e.message}finally{draining=false;overlay();if(before!==JSON.stringify(jobs)&&state.page==='connected'&&!syncEditorActive())render();window.MobileChrome?.paint()}}
 callPc=async function(method,path,data,base=pcUrl){
   if(base===pcUrl&&path==='/api/mobile/notes'){
     if(method==='GET'){noteVersion=await network('GET','/api/mobile/notes-v2',undefined,base);return noteVersion.notes.filter(n=>!n.deleted_at)}
     if(method==='POST'){
       if(!noteVersion)throw Error('Actualise les notes avant de les envoyer. Ton brouillon reste sur le téléphone.');
       const incoming=data?.notes;if(!Array.isArray(incoming))throw Error('Notes invalides.');
       const ids=new Set(incoming.map(n=>n.id)),combined=[...incoming,...noteVersion.notes.filter(n=>!ids.has(n.id))];
       for(const note of incoming)if(noteVersion.notes.some(n=>n.id===note.id&&n.deleted_at)&&!note.deleted_at)throw Error('Cette note est archivée sur le PC. Restaure-la avant de la modifier.');
       noteVersion=await network('POST','/api/mobile/notes-v2',{revision:noteVersion.revision,notes:combined},base);return {ok:true,count:noteVersion.notes.length};
     }
   }

   if(!['POST','PUT'].includes(method)||!/^\/api\/(tasks|shopping|events|recipes)(?:\/\d+)?$/.test(path)||base!==pcUrl)return network(method,path,data,base);
   if(!pcUrl)throw Error('Configure d’abord ton PC.');
   const m=path.match(/^\/api\/([^/]+)(?:\/(\d+))?$/),row=m[2]?(pc[m[1]]||[]).find(x=>String(x.id)===m[2]):null,original={};
   if(method==='PUT'){if(!row)throw Error('Actualise cet élément avant de le modifier.');for(const key of Object.keys(data||{})){if(!(key in row))throw Error('Actualise cet élément avant de modifier '+key+'.');original[key]=row[key]}}
   const job={id:id(),method,path,data:JSON.parse(JSON.stringify(data||{})),original,base:pcUrl,createdAt:new Date().toISOString()};jobs.push(job);try{saveJobs()}catch(e){jobs.pop();throw e}overlay();error='Modification conservée sur le téléphone, en attente de confirmation du PC.';drain();return {queued:true,id:'local-'+job.id};
 };
 const previousPull=syncPull;syncPull=async function(options={}){if(options.quiet&&(document.visibilityState==='hidden'||syncEditorActive()))return;await previousPull(options);if(online){try{await capabilities()}catch(e){error=e.message}cache();overlay();await drain()}else overlay();if(!options.quiet&&!syncEditorActive())render()};
 async function editEvent(item){if(String(item.id).startsWith('local-')){alert('Cette création doit d’abord être confirmée par le PC.');return}if(item.recurrence&&item.recurrence!=='none'){alert('Modifie cette série ou son occurrence depuis le calendrier Windows pour conserver ses règles de répétition.');return}const title=prompt('Titre du rendez-vous',item.title||'');if(title===null)return;const date=prompt('Date (AAAA-MM-JJ)',item.event_date||item.instance_date||'');if(date===null)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)){alert('Date invalide.');return}const time=prompt('Heure (HH:MM), vide si sans horaire',item.start_time||'');if(time===null)return;if(time&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)){alert('Heure invalide.');return}try{await callPc('PUT','/api/events/'+item.id,{title:title.trim()||item.title,event_date:date,start_time:time||null});render()}catch(e){alert(e.message)}}
 function renderSyncOutbox(root){const box=panel(root,'Modifications conservées sur ce téléphone');box.id='syncOutboxPanel';const pending=jobs.filter(j=>j.base===pcUrl);box.append(el('p',{class:'muted'},pending.length?pending.length+' modification(s) en attente ou en conflit.':'Toutes les modifications envoyées ont été confirmées par le PC.'));
   const retry=el('button',{class:'action'},'Réessayer la synchronisation');retry.onclick=async()=>{await drain();await syncPull()};box.append(retry);
   for(const job of pending){const line=el('div',{class:'panel'});line.append(el('strong',{},job.data.title||job.data.name||job.path),el('p',{class:'muted'},job.conflict||'En attente de connexion.'));
    if(job.conflict){const keepPc=el('button',{class:'action'},'Garder la version du PC');keepPc.onclick=()=>{if(!confirm('Abandonner cette modification locale et garder la version du PC ?'))return;jobs=jobs.filter(x=>x.id!==job.id);saveJobs();syncPull()};const keepMine=el('button',{class:'action'},'Revoir et envoyer ma version');keepMine.onclick=async()=>{if(!confirm('Relire la version du PC puis envoyer les champs de ta version locale ?'))return;try{await previousPull();const m=job.path.match(/^\/api\/([^/]+)\/(\d+)$/),current=(pc[m[1]]||[]).find(x=>String(x.id)===m[2]);if(!current)throw Error('L’élément n’existe plus sur le PC. Exporte ta sauvegarde pour garder le texte.');job.original=Object.fromEntries(Object.keys(job.data).map(k=>[k,current[k]]));job.id=id();delete job.conflict;saveJobs();await drain();await syncPull()}catch(e){alert(e.message)}};line.append(keepPc,keepMine)}box.append(line)}
 }
 const previousConnected=connectedView;
 connectedView=function(root){previousConnected(root);renderSyncOutbox(root);
   for(const [index,label] of [...root.querySelectorAll('label.item')].entries()){
     const item=(pc[tab]||[])[index];if(!item||!['tasks','shopping'].includes(tab))continue;const checkbox=label.querySelector('input[type=checkbox]');
     if(String(item.id).startsWith('local-')){checkbox.disabled=true;label.append(el('small',{},' · création en attente'));continue}
     const edit=el('button',{type:'button',class:'action'},'Modifier');edit.onclick=async event=>{event.preventDefault();event.stopPropagation();const text=prompt(tab==='tasks'?'Nom de la tâche':'Nom de l’article',item.title||item.name||'');if(text===null||!text.trim())return;const data=tab==='tasks'?{title:text.trim()}:{name:text.trim()};if(tab==='shopping'){const quantity=prompt('Quantité',item.quantity||'');if(quantity===null)return;data.quantity=quantity}try{await callPc('PUT','/api/'+tab+'/'+item.id,data);render()}catch(e){alert(e.message)}};
     const remove=el('button',{type:'button',class:'action'},'Archiver');remove.onclick=async event=>{event.preventDefault();event.stopPropagation();if(!confirm('Archiver cet élément sur le PC ?'))return;try{await callPc('PUT','/api/'+tab+'/'+item.id,{archived:true});render()}catch(e){alert(e.message)}};label.append(edit,remove);
   }

 };
 const previousGrimoire=grimoireView;grimoireView=function(root){previousGrimoire(root);const active=pc.recipes.find(x=>String(x.id)===openedRecipeId);if(active){const edit=el('button',{class:'action'},'Modifier cette recette');edit.onclick=async()=>{const title=prompt('Nom de la recette',active.title||'');if(title===null)return;const recipe=prompt('Préparation',active.recipe||'');if(recipe===null)return;try{await callPc('PUT','/api/recipes/'+active.id,{title:title.trim()||active.title,recipe});render()}catch(e){alert(e.message)}};root.querySelector('#kitchenRecipe')?.append(edit)}};
 document.addEventListener('click',event=>{const button=event.target.closest?.('[data-page]');if(!pcUrl||!button||!['tasks','shopping','calendar'].includes(button.dataset.page))return;event.preventDefault();event.stopImmediatePropagation();tab=button.dataset.page;state.page='connected';save();render();syncPull({quiet:true})},true);
 window.atelierOffline={editEvent,renderOutbox:renderSyncOutbox,get hasCache(){return cached},get pending(){return jobs},apply:overlay,drain};load();overlay();
 window.addEventListener('online',()=>{drain();syncPull({quiet:true})});setInterval(()=>{if(document.visibilityState==='visible'&&!syncEditorActive())drain()},15000);
 if(pcUrl){syncPull({quiet:true})}render();
})();
